content.query:
let devices = DeviceInfo
| where TimeGenerated > ago(30d)
| summarize arg_max(TimeGenerated, MachineGroup, DeviceType, IsInternetFacing) by DeviceId, DeviceName
| extend GroupName = iff(isempty(MachineGroup), 'Unassigned', MachineGroup)
| where ('*' in ({DeviceGroup}) or GroupName in ({DeviceGroup}));
let acEvents = DeviceEvents
| where TimeGenerated > ago({TimeRange})
| where ActionType startswith 'AppControl'
| join kind=inner devices on DeviceId;
let perDevice = acEvents
| summarize BlockedCount = countif(ActionType has 'Blocked'), AuditedCount = countif(ActionType has 'Audited'), RevokedCount = countif(ActionType has 'Revoked') by DeviceId;
let kpiEnforced = perDevice | where BlockedCount > 0 | summarize Metric = 'Devices Emitting Enforced Blocks', Value = toreal(dcount(DeviceId));
let kpiAuditOnly = perDevice | where BlockedCount == 0 and AuditedCount > 0 | summarize Metric = 'Audit-Only Devices (Needs Enforcement)', Value = toreal(dcount(DeviceId));
let kpiBlocked = acEvents | where ActionType has 'Blocked' | summarize Metric = 'Total Blocked Executions', Value = toreal(count());
let kpiAudited = acEvents | where ActionType has 'Audited' | summarize Metric = 'Total Audited Executions', Value = toreal(count());
let kpiRevoked = acEvents | where ActionType has 'Revoked' | summarize Metric = 'Vulnerable Driver / Revoked Image Blocks', Value = toreal(count());
union kpiEnforced, kpiAuditOnly, kpiBlocked, kpiAudited, kpiRevoked
